// ICU-lite message formatting: {name}, {n, plural, ...}, {g, select, ...}
// Real recursive-descent parser (no regex parsing of message bodies).

/**
 * Parse a message string into an AST.
 * Nodes:
 *   { type: 'text', value }
 *   { type: 'interpolation', name }
 *   { type: 'plural', name, options: Map<key, nodes> }   keys: '=N' | category | 'other'
 *   { type: 'select', name, options: Map<key, nodes> }   keys: literal | 'other'
 */
export function parse(src) {
  let pos = 0;

  function fail(why) {
    const ctx = src.slice(Math.max(0, pos - 10), pos + 10);
    throw new SyntaxError(`msgcat: ${why} at index ${pos} near ${JSON.stringify(ctx)}`);
  }

  function skipWs() {
    while (pos < src.length && /\s/.test(src[pos])) pos++;
  }

  // A run of characters that is neither whitespace nor a structural char.
  function readToken() {
    let start = pos;
    while (pos < src.length && !/[\s{},]/.test(src[pos])) pos++;
    if (start === pos) fail('expected a token');
    return src.slice(start, pos);
  }

  function expect(ch) {
    if (src[pos] !== ch) fail(`expected '${ch}'`);
    pos++;
  }

  // Parse a sequence of text/placeholder nodes.
  // Stops (without consuming) at a closing brace when nested === false.
  function parseNodes(nested) {
    const nodes = [];
    let text = '';
    const flush = () => {
      if (text !== '') {
        nodes.push({ type: 'text', value: text });
        text = '';
      }
    };
    while (pos < src.length) {
      const ch = src[pos];
      if (ch === '{') {
        flush();
        pos++;
        nodes.push(parsePlaceholder());
      } else if (ch === '}') {
        if (!nested) break;
        break;
      } else {
        text += ch;
        pos++;
      }
    }
    flush();
    return nodes;
  }

  function parseVariantKey() {
    skipWs();
    let key;
    if (src[pos] === '=') {
      pos++;
      key = '=' + readToken(); // exact numeric match, e.g. =0
    } else {
      key = readToken();
    }
    skipWs();
    expect('{');
    pos++;
    const body = parseNodes(true);
    expect('}');
    pos++;
    return [key, body];
  }

  function parsePlaceholder() {
    skipWs();
    const name = readToken();
    skipWs();

    // Simple interpolation: {name}
    if (src[pos] === '}') {
      pos++;
      return { type: 'interpolation', name };
    }

    expect(',');
    skipWs();
    const kind = readToken();
    if (kind !== 'plural' && kind !== 'select') {
      fail(`unsupported argument type '${kind}'`);
    }

    const options = {};
    while (true) {
      skipWs();
      if (pos >= src.length) fail(`unterminated ${kind} block`);
      if (src[pos] === '}') {
        pos++;
        break;
      }
      const [key, body] = parseVariantKey();
      options[key] = body;
    }
    return { type: kind, name, options };
  }

  const nodes = parseNodes(false);
  if (pos < src.length) fail('unexpected closing brace');
  return nodes;
}

function formatNumber(value, locale) {
  try {
    return new Intl.NumberFormat(locale).format(value);
  } catch {
    return String(value);
  }
}

function formatNodes(nodes, values, locale, num) {
  let out = '';
  for (const node of nodes) {
    switch (node.type) {
      case 'text':
        // '#' is only meaningful inside a plural variant; the innermost
        // enclosing plural wins for nested plurals.
        out += num === undefined ? node.value : node.value.replace(/#/g, formatNumber(num, locale));
        break;
      case 'interpolation': {
        const v = values[node.name];
        out += v === undefined ? '' : String(v);
        break;
      }
      case 'plural': {
        const raw = values[node.name];
        if (raw === undefined) throw new Error(`msgcat: missing value for '{${node.name}}'`);
        const n = Number(raw);
        if (Number.isNaN(n)) throw new Error(`msgcat: '{${node.name}}' is not a number: ${String(raw)}`);
        // Exact matches (=N) take precedence over plural categories.
        let chosen;
        const exact = '=' + String(raw);
        const exactNum = '=' + String(n);
        if (exact in node.options) chosen = exact;
        else if (exactNum in node.options) chosen = exactNum;
        else {
          chosen = new Intl.PluralRules(locale).select(n);
          if (!(chosen in node.options)) chosen = 'other';
        }
        out += formatNodes(node.options[chosen], values, locale, n);
        break;
      }
      case 'select': {
        const raw = values[node.name];
        if (raw === undefined) throw new Error(`msgcat: missing value for '{${node.name}}'`);
        const key = String(raw) in node.options ? String(raw) : 'other';
        out += formatNodes(node.options[key], values, locale, num);
        break;
      }
    }
  }
  return out;
}

/**
 * Format an ICU-lite message.
 * @param {string|Array} msg  message string (or pre-parsed AST)
 * @param {object} [values]   placeholder values
 * @param {string} [locale]   BCP-47 locale for PluralRules/number format
 */
export function format(msg, values = {}, locale = 'en') {
  const ast = typeof msg === 'string' ? parse(msg) : msg;
  return formatNodes(ast, values ?? {}, locale, undefined);
}

