// Extractor CLI: scans .js files for t('message id') calls (string-literal
// args only, quick scan — no full JS parsing) and merges ids into catalog.json.
//
// Usage: node src/extract.mjs [files or dirs...] [--out catalog.json]
//   - dirs are scanned recursively for *.js
//   - existing catalog entries are never overwritten; new ids get "" defaults

import { readdirSync, readFileSync, statSync, existsSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

// Quick parser: t( followed by a single string literal, then ',' or ')'.
const T_CALL = /\bt\(\s*(?:'([^'\\\n]*)'|"([^"\\\n]*)")\s*[,)]/g;

export function findJsFiles(target) {
  const abs = resolve(target);
  const st = statSync(abs);
  if (st.isFile()) return abs.endsWith('.js') ? [abs] : [];
  const found = [];
  for (const entry of readdirSync(abs, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    if (entry.name === 'node_modules' || entry.name.startsWith('.')) continue;
    const child = join(abs, entry.name);
    if (entry.isDirectory()) found.push(...findJsFiles(child));
    else if (entry.isFile() && entry.name.endsWith('.js')) found.push(child);
  }
  return found;
}

export function extractIds(files) {
  const ids = new Set();
  for (const file of files) {
    const src = readFileSync(file, 'utf8');
    for (const m of src.matchAll(T_CALL)) {
      const id = m[1] ?? m[2];
      if (id !== '') ids.add(id);
    }
  }
  return [...ids].sort();
}

export function updateCatalog(ids, catalogPath) {
  let catalog = {};
  if (existsSync(catalogPath)) {
    catalog = JSON.parse(readFileSync(catalogPath, 'utf8'));
    if (catalog === null || typeof catalog !== 'object' || Array.isArray(catalog)) {
      throw new Error(`msgcat: ${catalogPath} does not contain a JSON object`);
