import { test } from 'node:test';
import assert from 'node:assert/strict';
import { format, parse } from '../src/format.mjs';

const PLURAL_EN = '{count, plural, =0 {no items} one {# item} other {# items}}';

test('simple interpolation', () => {
  assert.equal(format('Hello {name}!', { name: 'Ada' }, 'en'), 'Hello Ada!');
  assert.equal(format('Hello {name}!', {}, 'en'), 'Hello !');
});

test('plural categories in en', () => {
  const f = (count) => format(PLURAL_EN, { count }, 'en');
  assert.equal(f(0), 'no items'); // exact match
  assert.equal(f(1), '1 item'); // one
  assert.equal(f(3), '3 items'); // other
});

test('plural categories in pl (few/many)', () => {
  const msg = '{count, plural, one {# plik} few {# pliki} many {# plików} other {# pliku}}';
  // Polish: 1 -> one; 2,3,4 (not 12-14) -> few; 5..21 etc -> many; 22 -> few again
  for (const [count, expected] of [
    [1, '1 plik'],
    [2, '2 pliki'],
    [5, '5 plików'],
    [22, '22 pliki'],
  ]) {
    assert.equal(new Intl.PluralRules('pl').select(count), count === 1 ? 'one' : count === 5 ? 'many' : 'few');
    assert.equal(format(msg, { count }, 'pl'), expected);
  }
});

test('exact match takes precedence over category', () => {
  const msg = '{n, plural, =1 {exactly one} one {category one} other {other}}';
  assert.equal(format(msg, { n: 1 }, 'en'), 'exactly one');
  assert.equal(format(msg, { n: 0 }, 'en'), 'other'); // no =0, no one(0) in en? en: 0 -> other
  const withZero = '{n, plural, =0 {zero} =1 {exactly one} one {category one} other {other}}';
  assert.equal(format(withZero, { n: 0 }, 'en'), 'zero');
  assert.equal(format(withZero, { n: 21 }, 'en'), 'category one'); // en one: integers ending in 1 except 11... actually 21 -> one
});

test('select falls back to other', () => {
  const msg = '{gender, select, female {her} male {his} other {their}}';
  assert.equal(format(msg, { gender: 'female' }, 'en'), 'her');
  assert.equal(format(msg, { gender: 'male' }, 'en'), 'his');
  assert.equal(format(msg, { gender: 'nonbinary' }, 'en'), 'their');
  assert.equal(format(msg, { gender: '' }, 'en'), 'their');
});

test('nested plural inside select', () => {
  const msg =
    '{gender, select,' +
    ' female {{count, plural, =0 {she has nothing} other {she has # items}}}' +
    ' other  {{count, plural, =0 {they have nothing} other {they have # items}}}' +
    '}';
  assert.equal(format(msg, { gender: 'female', count: 3 }, 'en'), 'she has 3 items');
  assert.equal(format(msg, { gender: 'female', count: 0 }, 'en'), 'she has nothing');
  assert.equal(format(msg, { gender: 'x', count: 5 }, 'en'), 'they have 5 items');
  assert.equal(format(msg, { gender: 'x', count: 0 }, 'en'), 'they have nothing');
});

test('innermost plural owns # in nested plurals', () => {
  const msg = '{a, plural, other {{b, plural, other {[a=#] [b=#]}}} }';
  assert.equal(format(msg, { a: 1, b: 2 }, 'en'), '[a=1] [b=2]');
});

test('parser handles nested braces without regex tricks', () => {
  const ast = parse('{g, select, x {a {n, plural, other {deep {v} }} }}');
  assert.equal(ast.length, 1);
  const sel = ast[0];
  assert.equal(sel.type, 'select');
  const inner = sel.options.x;
  assert.equal(inner[0].type, 'text');
  assert.equal(inner[1].type, 'plural');
  assert.deepEqual(inner[1].options.other[1], { type: 'interpolation', name: 'v' });
});

test('syntax errors are reported', () => {
  assert.throws(() => parse('{name'));
  assert.throws(() => parse('oops }'));
  assert.throws(() => parse('{x, number, one {a}}')); // unsupported type
});

