import { test } from 'node:test';
import assert from 'node:assert/strict';
import { cpSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { findJsFiles, extractIds, main } from '../src/extract.mjs';

const FIXTURES = new URL('./fixtures', import.meta.url).pathname;

function freshDir() {
  const dir = mkdtempSync(join(tmpdir(), 'msgcat-'));
  cpSync(FIXTURES, dir, { recursive: true });
  return dir;
}

test('findJsFiles scans recursively for .js', () => {
  const files = findJsFiles(join(FIXTURES, 'src'));
  assert.equal(files.length, 1);
  assert.match(files[0], /src[/\\]app\.js$/);
});

test('extractIds picks up only string-literal t() calls', () => {
  const ids = extractIds([join(FIXTURES, 'src', 'app.js')]);
  assert.deepEqual(ids, ['app.cancel', 'app.farewell', 'app.greeting', 'app.save', 'app.title']);
});

test('extractor merges without clobbering translated entries', () => {
  const dir = freshDir();
  try {
    const out = join(dir, 'catalog.json');
    // Fixture catalog.json already contains a translated app.title.
    main([join(dir, 'src'), '--out', out]);

    const catalog = JSON.parse(readFileSync(out, 'utf8'));
    assert.deepEqual(catalog, {
      'app.title': 'Tytuł aplikacji', // preserved translation
      'app.greeting': '', // newly added defaults
      'app.cancel': '',
      'app.save': '',
      'app.farewell': '',
    });
    assert.ok(catalog['app.title'] !== '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('extractor creates catalog when none exists', () => {
  const dir = freshDir();
  try {
    rmSync(join(dir, 'catalog.json'));
    const out = join(dir, 'out', 'catalog.json');
    main([join(dir, 'src'), '--out', out]);
    const catalog = JSON.parse(readFileSync(out, 'utf8'));
    assert.equal(catalog['app.title'], '');
    assert.equal(Object.keys(catalog).length, 5);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

